const update = $input.first().json;
const message = update.message ?? update.edited_message;
if (!message?.text || !message?.chat?.id) return [];
const text = message.text.trim();
// SECURITY: after the first setup message, paste your own Telegram chat ID here.
const OWNER_CHAT_ID = 'PASTE_YOUR_TELEGRAM_CHAT_ID_HERE';
const isOwner = OWNER_CHAT_ID !== 'PASTE_YOUR_TELEGRAM_CHAT_ID_HERE' && String(message.chat.id) === OWNER_CHAT_ID;
const match = text.match(/^\/start(?:@\w+)?(?:\s+([\s\S]+))?$/i);
const topic = (match?.[1] || 'Create a fresh, surprising supernatural mystery with a unique setting').slice(0, 180);
const prompt = `You are the head writer for an original Hindi 2D horror animation YouTube channel.
Create a completely original fictional supernatural mystery in natural spoken Hindi (Devanagari), suitable for a 4–6 minute narration. Do not copy existing films, stories, internet creepypastas, copyrighted characters, or real incidents. No graphic gore. Keep it suspenseful, emotionally engaging, and give it a memorable twist ending.
Story seed from the channel owner: ${topic}
Return ONLY valid JSON, no markdown fences, with this exact schema:
{"title":"Hindi title under 90 characters","description":"SEO-friendly Hindi description, 2-4 sentences, followed by a short fictional-story note","tags":["10-15 short YouTube tags"],"hashtags":["3-5 hashtags without spaces"],"thumbnail_text":"short Hindi thumbnail phrase, 2-5 words","scenes":[{"visual":"one concise English visual description of the environment and action for a dark 2D cartoon illustration","narration":"Hindi narration for this scene, about 45-70 words, written for a narrator"}]}
Create 8 scenes. Each scene narration must be natural, complete, and move the same story forward. Total narration should be roughly 450-600 Hindi words. Ensure the first scene has a strong hook and the final scene resolves the mystery. Tags should be plain text, not hashtags. JSON strings must escape quotation marks and newlines correctly.`;
return [{ json: { chat_id: String(message.chat.id), isStart: Boolean(match && isOwner), isOwner, topic, prompt } }];

const response = $input.first().json;
const raw = response.candidates?.[0]?.content?.parts?.map(part => part.text || '').join('').trim();
if (!raw) throw new Error('Gemini returned no story text. Check the API key, model and free-tier limits.');
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let story;
try { story = JSON.parse(cleaned); } catch (error) { throw new Error('Gemini output was not valid JSON: ' + error.message); }
if (!story.title || !story.description || !Array.isArray(story.scenes) || story.scenes.length < 5 || story.scenes.length > 12) throw new Error('Story JSON is missing required fields or does not contain 5-12 scenes.');
for (const [index, scene] of story.scenes.entries()) { if (!scene.narration || String(scene.narration).trim().length < 25) throw new Error('Scene ' + (index + 1) + ' narration is missing or too short.'); }
if (!Array.isArray(story.tags)) story.tags = [];
if (!Array.isArray(story.hashtags)) story.hashtags = [];
const chat_id = $('Parse Telegram Command').first().json.chat_id;
return [{ json: { title: String(story.title).slice(0, 100), story_json: JSON.stringify(story), chat_id, scene_count: story.scenes.length } }];

